const BOOKS=[{"a": "Krystian Brodacki", "t": "Historia jazzu w Polsce", "y": "PWM, 2010", "d": "Fundament polskiej jazzologii: 626 stron, 12 rozdziałów, dyskografia i bibliografia. Jedyna pełna monografia dziejów jazzu nad Wisłą — od lat 20. XX w. po współczesność.", "tags": ["monografia", "kanon"], "hot": true, "url": "https://pwm.com.pl/pl/sklep/pub/historia-jazzu-w-polsce,krystian-brodacki,17004,ksiegarnia.htm", "y_en": "PWM, 2010", "d_en": "The foundation of Polish jazz scholarship: 626 pages, 12 chapters, a discography and a bibliography. The only complete monograph on the history of jazz in Poland — from the 1920s to the present day.", "tags_en": ["monograph", "canon"]}, {"a": "Igor Pietraszewski", "t": "Jazz w Polsce. Wolność improwizowana / Jazz in Poland: Improvised Freedom", "y": "Nomos 2012 / Peter Lang 2014", "d": "Socjolog i saksofonista o rolach jazzu w PRL i III RP: od muzyki zakazanej, przez wspieraną, po rynkową. Wydanie angielskie w serii „Jazz under State Socialism”.", "tags": ["naukowa", "PL+EN"], "hot": true, "url": "https://www.peterlang.com/document/1047698", "y_en": "Nomos 2012 / Peter Lang 2014", "d_en": "A sociologist and saxophonist on the roles jazz played in the Polish People's Republic and in post-1989 Poland: from forbidden music, through officially supported music, to a market product. The English edition appeared in the \"Jazz under State Socialism\" series.", "tags_en": ["academic", "PL+EN"]}, {"a": "Andrzej Wasylewski (oprac.)", "t": "Jazzowe dzieje Polaków. Biografia wielogłosowa", "y": "IPN, 2018", "d": "Opowieść chóralna twórców gatunku: Matuszkiewicz, Ptaszyn, Urbaniak, Trzaskowski, Namysłowski, Karolak, Stańko — plus 4 DVD z filmami i koncertami.", "tags": ["świadectwa", "+4 DVD"], "hot": true, "url": "https://ipn.gov.pl/pl/publikacje/ksiazki/46476,Jazzowe-dzieje-Polakow-Biografia-wieloglosowa.html", "y_en": "IPN (Institute of National Remembrance), 2018", "d_en": "A choral account by the creators of the genre: Matuszkiewicz, Ptaszyn, Urbaniak, Trzaskowski, Namysłowski, Karolak, Stańko — plus 4 DVDs with films and concerts.", "tags_en": ["first-hand accounts", "+4 DVD"]}, {"a": "Maciej Lewenstein", "t": "Polish Jazz Recordings and Beyond (vol. 1–2)", "y": "2014; wyd. rozszerz.", "d": "Anglojęzyczny przewodnik po 1700+ płytach polskiego jazzu w formacie Penguin Guide — pisany przez fizyka kwantowego z kolekcją 8000 albumów. Jedyna taka pozycja na świecie.", "tags": ["dyskografia", "EN"], "hot": true, "url": "https://jazzforum.com.pl/main/artykul/polish-jazz-recordings-and-beyond", "y_en": "2014; expanded ed.", "d_en": "An English-language guide to 1,700+ Polish jazz records in the Penguin Guide format — written by a quantum physicist with a collection of 8,000 albums. The only book of its kind in the world.", "tags_en": ["discography", "EN"]}, {"a": "Krzysztof Karpiński", "t": "Był jazz. Krzyk jazz-bandu w międzywojennej Polsce", "y": "Wyd. Literackie, 2014", "d": "Pierwsza książka w całości o jazzie II Rzeczypospolitej — Karasiński, Gold, Petersburski, Rosner — na barwnym tle obyczajowym epoki.", "tags": ["1918–1939"], "url": "https://lubimyczytac.pl/ksiazka/227248/byl-jazz-krzyk-jazz-bandu-w-miedzywojennej-polsce", "y_en": "Wydawnictwo Literackie, 2014", "d_en": "The first book devoted entirely to jazz in the Second Polish Republic — Karasiński, Gold, Petersburski, Rosner — set against the colourful social backdrop of the era.", "tags_en": ["1918–1939"]}, {"a": "Leopold Tyrmand", "t": "U brzegów jazzu", "y": "1957, wznowienia", "d": "Klasyk-świadectwo: pisarz, który jazz w Polsce współtworzył (Zaduszki, festiwale), pisze o nim z pasją pioniera. Lektura obowiązkowa dla klimatu epoki.", "tags": ["klasyk", "świadectwo"], "url": "https://lubimyczytac.pl/ksiazka/4957896/u-brzegow-jazzu", "y_en": "1957, reissues", "d_en": "A classic and a first-hand account: a writer who helped create jazz in Poland (Zaduszki, festivals) writes about it with a pioneer's passion. Essential reading for the atmosphere of the era.", "tags_en": ["classic", "first-hand account"]}, {"a": "Magdalena Grzebałkowska", "t": "Komeda. Osobiste życie jazzu / Komeda: A Private Life in Jazz", "y": "Znak 2018 / Equinox 2021", "d": "Wielka reporterska biografia Komedy — a przy okazji historia polskiego jazzu w pigułce. Bestseller przetłumaczony na angielski.", "tags": ["biografia", "PL+EN"], "hot": true, "url": "https://lubimyczytac.pl/ksiazka/4808212/komeda-osobiste-zycie-jazzu", "y_en": "Znak 2018 / Equinox 2021", "d_en": "A major work of reportage on Komeda's life — and, along the way, the history of Polish jazz in a nutshell. A bestseller translated into English.", "tags_en": ["biography", "PL+EN"]}, {"a": "Tomasz Stańko, Rafał Księżyk", "t": "Desperado! Autobiografia", "y": "Wyd. Literackie, 2010", "d": "Rzeka-rozmowa z największym polskim trębaczem: free jazz, nałogi, ECM, filozofia improwizacji. Wydana także po angielsku.", "tags": ["autobiografia", "PL+EN"], "url": "https://www.wydawnictwoliterackie.pl/produkt/199/desperado-autobiografia", "y_en": "Wydawnictwo Literackie, 2010", "d_en": "A book-length conversation with Poland's greatest trumpeter: free jazz, addictions, ECM, the philosophy of improvisation. Also published in English.", "tags_en": ["autobiography", "PL+EN"]}, {"a": "Sebastian Rerak", "t": "Chłepcąc ciekły hel. Historia yassu", "y": "2013", "d": "Ponad 500 stron i sześćdziesięciu rozmówców: jedyna monografia yassowej rewolty lat 90. — Miłość, Mózg, Trytony, Kury.", "tags": ["yass", "lata 90."], "url": "https://lubimyczytac.pl/ksiazka/172524/chlepcac-ciekly-hel-historia-yassu", "y_en": "2013", "d_en": "Over 500 pages and sixty interviewees: the only monograph on the yass revolt of the 1990s — Miłość, Mózg, Trytony, Kury.", "tags_en": ["yass", "the 1990s"]}, {"a": "Andrzej Schmidt", "t": "Historia jazzu", "y": "Polihymnia, wyd. jednotomowe", "d": "Jedyna polska pełna historia jazzu światowego (do 2000 r.) — niezbędne tło dla dziejów sceny rodzimej. Trzy tomy w jednym, czyta się jak powieść.", "tags": ["kontekst światowy"], "url": "https://lubimyczytac.pl/ksiazka/204363/historia-jazzu", "y_en": "Polihymnia, one-volume edition", "d_en": "The only complete Polish history of jazz worldwide (up to the year 2000) — indispensable background for the story of the home scene. Three volumes in one, and it reads like a novel.", "tags_en": ["global context"]}, {"a": "Jacek Niedziela-Meira", "t": "Historia jazzu. 100 wykładów", "y": "2014", "d": "Podręcznikowe (a przy tym przystępne) ujęcie historii gatunku przez wykładowcę i kontrabasistę — z kontekstem społecznym i funkcją jazzu w kulturze.", "tags": ["podręcznik"], "url": "https://lubimyczytac.pl/ksiazka/83348/historia-jazzu-100-wykladow", "y_en": "2014", "d_en": "A textbook (yet accessible) treatment of the genre's history by a lecturer and double bass player — with social context and the role of jazz in culture.", "tags_en": ["textbook"]}, {"a": "red. Rafał Ciesielski", "t": "Jazz w kulturze polskiej, t. 1–4", "y": "2014–2022", "d": "Seria pokonferencyjna (Zielona Góra/UJ) — jedyne cykliczne naukowe forum polskiej jazzologii: recepcja, krytyka, edukacja, regionalne sceny.", "tags": ["naukowa", "seria"], "url": "https://www.alenuty.pl/pl/p/Jazz-w-kulturze-polskiej-tom-1-Rafal-Ciesielski/10705", "y_en": "2014–2022", "d_en": "A series of conference volumes (Zielona Góra/UJ) — the only recurring academic forum for Polish jazz studies: reception, criticism, education, regional scenes.", "tags_en": ["academic", "series"]}, {"a": "Culture.pl", "t": "A Foreigner's Guide to Polish Jazz", "y": "online, EN", "d": "Najlepszy darmowy anglojęzyczny przewodnik wprowadzający — idealny do podsyłania zagranicznym znajomym.", "tags": ["online", "EN"], "url": "https://culture.pl/en/article/a-foreigners-guide-to-polish-jazz", "y_en": "online, EN", "d_en": "The best free English-language introductory guide — perfect for sending to friends abroad.", "tags_en": ["online", "EN"]}, {"a": "Wikipedia (EN)", "t": "Polish jazz", "y": "online", "d": "Solidne hasło przeglądowe z bibliografią — dobry punkt startowy do dalszych poszukiwań.", "tags": ["online", "EN"], "url": "https://en.wikipedia.org/wiki/Polish_jazz", "y_en": "online", "d_en": "A solid overview entry with a bibliography — a good starting point for further exploration.", "tags_en": ["online", "EN"]}];
